# Performance, weight and balance: PHAK chapters 10 and 11; Aircraft Weight and Balance Handbook
# FAA-H-8083-1B; AC 91-79 (runway overruns). ACS I.F. Every chart is replaced by numbers in the stem.
ITEMS = [
    # ---------- Practice Test 1 ----------
    S(1, 3, "Center of gravity", "Basic empty weight is 2,050 pounds with a moment of 75,850 pound-inches. You load 360 pounds in front seats at 37.0 inches, 180 pounds in rear seats at 73.0, 60 gallons of fuel at 48.0 and 40 pounds of baggage at 95.0. Where is the CG?",
      ["About 41.3 inches aft of datum", "About 39.8 inches aft of datum", "About 42.6 inches aft of datum"],
      "Fuel is 60 x 6 = 360 pounds. Moments: 75,850 + 13,320 + 13,140 + 17,280 + 3,800 = 123,390. Weight: 2,050 + 360 + 180 + 360 + 40 = 2,990. CG = 123,390 / 2,990, about 41.3 inches."),
    S(1, 3, "Weight shift", "The airplane weighs 3,100 pounds with its CG at 47.0 inches; the aft limit is 46.0. How much baggage must move from the 120-inch station to the 80-inch station?",
      ["At least 78 pounds", "At least 40 pounds", "At least 31 pounds"],
      "Weight moved = total weight x CG change / distance moved = 3,100 x 1.0 / 40 = 77.5 pounds, so move at least 78 pounds."),
    S(1, 2, "Overweight", "Maximum takeoff weight is 3,400 pounds. Fully fueled and loaded, the airplane weighs 3,460 pounds. How much avgas must you remove to take off at the limit?",
      ["10 gallons", "60 gallons", "6 gallons"],
      "The airplane is 60 pounds over. Avgas weighs 6 pounds per gallon, so 60 / 6 = 10 gallons."),
    S(1, 2, "Takeoff weight", "According to the PHAK, a 10 percent increase in takeoff weight increases the takeoff distance by about how much?",
      ["At least 21 percent", "About 10 percent", "About 5 percent"],
      "More weight means a higher takeoff speed and slower acceleration. The PHAK (chapter 11) says a 10 percent weight increase raises takeoff distance by at least 21 percent."),
    S(1, 3, "Hydroplaning", "The main tires are inflated to 36 psi. About what is the minimum dynamic hydroplaning speed?",
      ["54 knots", "45 knots", "72 knots"],
      "Minimum dynamic hydroplaning speed is about 9 times the square root of the tire pressure in psi: 9 x 6 = 54 knots (PHAK chapter 11)."),
    S(1, 3, "Crosswind component", "You will land on runway 27 with the wind from 300 degrees at 24 knots. What is the crosswind component?",
      ["12 knots", "21 knots", "24 knots"],
      "The wind is 30 degrees off the runway. Crosswind = 24 x sin 30 = 24 x 0.5 = 12 knots. The headwind component is 24 x cos 30, about 21 knots."),
    # ---------- Practice Test 2 ----------
    S(2, 3, "Center of gravity", "An airplane weighs 2,800 pounds with its CG at 40.0 inches. You add 100 pounds at the 90-inch station. Where is the new CG?",
      ["About 41.7 inches", "About 42.5 inches", "About 40.9 inches"],
      "Old moment 2,800 x 40.0 = 112,000. Added moment 100 x 90 = 9,000. New CG = 121,000 / 2,900, about 41.7 inches."),
    S(2, 3, "Useful load", "Maximum takeoff weight is 3,600 pounds and basic empty weight is 2,350. You carry 680 pounds of people and 50 pounds of baggage. About how much avgas can you load?",
      ["About 86 gallons", "About 104 gallons", "About 120 gallons"],
      "Useful load = 3,600 - 2,350 = 1,250 pounds. After 730 pounds of people and bags, 520 pounds are left for fuel: 520 / 6 = about 86 gallons."),
    S(2, 3, "Landing weight", "You take off at 4,600 pounds in an airplane with a 4,400-pound maximum landing weight. It burns 15 gallons of avgas an hour. About how long must you fly before landing at the limit?",
      ["About 2 hours 13 minutes", "About 13 minutes", "About 1 hour 20 minutes"],
      "You must burn 200 pounds, or 200 / 6 = 33.3 gallons. At 15 gallons per hour that takes about 2.22 hours, or 2 hours 13 minutes."),
    S(2, 2, "Range", "In a propeller airplane, which speed gives the greatest range in still air?",
      ["The speed for the maximum lift-to-drag ratio", "The speed for minimum power required", "The maximum cruise speed"],
      "In a propeller airplane, maximum range is flown at the L/D max speed. Minimum power required gives maximum endurance, the longest time aloft (PHAK chapter 11)."),
    S(2, 2, "Runway slope", "How does an upsloping runway affect takeoff?",
      ["It lengthens the takeoff run", "It shortens the takeoff run", "It does not affect the takeoff run"],
      "On an upslope part of the airplane's weight acts against acceleration, so the takeoff run is longer. A downslope shortens takeoff but lengthens landings."),
    S(2, 3, "Tailwind landing", "According to the PHAK, a tailwind of about 10 percent of the landing airspeed increases the landing distance by about how much?",
      ["About 21 percent", "About 10 percent", "About 50 percent"],
      "Landing distance varies with the square of groundspeed at touchdown. A tailwind of 10 percent of the landing speed raises groundspeed 10 percent and landing distance about 21 percent (PHAK chapter 11)."),
    # ---------- Drill only ----------
    S(0, 3, "Percent MAC", "The CG is at 45.0 inches. The leading edge of the mean aerodynamic chord is at 30.0 inches and the MAC is 60.0 inches long. Where is the CG in percent of MAC?",
      ["25 percent", "75 percent", "50 percent"],
      "Percent MAC = (CG - LEMAC) / MAC x 100 = (45.0 - 30.0) / 60.0 x 100 = 25 percent (FAA-H-8083-1B)."),
    S(0, 3, "Ballast", "An airplane weighs 2,500 pounds with its CG at 38.0 inches, forward of the 40.0-inch forward limit. How much ballast must you add at the 120-inch station to move the CG to 40.0?",
      ["About 63 pounds", "About 42 pounds", "About 125 pounds"],
      "Ballast = total weight x CG change / (ballast arm - new CG) = 2,500 x 2.0 / (120 - 40) = 5,000 / 80 = 62.5, about 63 pounds."),
    S(0, 3, "Weight shift", "In a 2,600-pound airplane, a 170-pound passenger moves from the 73-inch seat to the 37-inch seat. How far does the CG move?",
      ["About 2.4 inches forward", "About 2.4 inches aft", "About 6.5 inches forward"],
      "CG change = weight moved x distance / total weight = 170 x 36 / 2,600 = about 2.4 inches. Moving the weight forward moves the CG forward."),
    S(0, 3, "Crosswind component", "You will land on runway 04 with the wind from 090 at 18 knots. About what is the crosswind component?",
      ["14 knots", "12 knots", "18 knots"],
      "The wind is 50 degrees off runway heading 040. Crosswind = 18 x sin 50, about 0.77, or about 14 knots. The headwind is 18 x cos 50, about 12 knots."),
    S(0, 2, "Pressure altitude", "Field elevation is 4,250 feet and the altimeter setting is 29.72. What is the pressure altitude?",
      ["4,450 feet", "4,050 feet", "4,250 feet"],
      "Pressure altitude = elevation + (29.92 - altimeter setting) x 1,000 = 4,250 + 200 = 4,450 feet."),
    S(0, 2, "Glide distance", "An airplane has a glide ratio of 10 to 1 and is 6,000 feet above the ground with no wind. About how far can it glide?",
      ["About 10 nm", "About 6 nm", "About 16 nm"],
      "It covers 10 feet forward for each foot down: 60,000 feet, about 9.9 nautical miles."),
    S(0, 2, "Density altitude", "How does high humidity affect density altitude and performance?",
      ["It raises density altitude and lowers performance", "It lowers density altitude and raises performance", "It has no effect on density altitude"],
      "Water vapor is lighter than dry air, so humid air is less dense. That raises density altitude and reduces engine, propeller and wing performance."),
    S(0, 3, "Center of gravity", "Empty weight is 1,650 pounds with a moment/1000 of 62.7. Pilot and passenger weigh 340 pounds, moment/1000 12.6. Fuel weighs 240 pounds, moment/1000 11.5. Where is the CG?",
      ["About 38.9 inches", "About 37.8 inches", "About 40.2 inches"],
      "Total moment/1000 = 62.7 + 12.6 + 11.5 = 86.8, or 86,800 pound-inches. Total weight = 2,230. CG = 86,800 / 2,230, about 38.9 inches."),
    S(0, 2, "Hydroplaning", "Which kind of hydroplaning comes from a locked wheel skidding on a wet runway?",
      ["Reverted rubber", "Dynamic", "Viscous"],
      "A locked wheel heats the water to steam under the tire, melting the rubber: reverted rubber hydroplaning. Dynamic hydroplaning comes from standing water at speed; viscous from a thin film on a smooth surface (PHAK chapter 11)."),
    S(0, 2, "Performance charts", "A chart gives a ground roll of 1,200 feet at 2,000 feet pressure altitude and 1,500 feet at 4,000 feet, other conditions the same. About what is it at 3,000 feet?",
      ["1,350 feet", "1,500 feet", "1,300 feet"],
      "3,000 feet is halfway between the chart values, so interpolate halfway: 1,200 + (1,500 - 1,200) / 2 = 1,350 feet."),
    S(0, 2, "Empty weight", "Under the current GAMA standard, what does basic empty weight include?",
      ["Unusable fuel and full engine oil", "Usable fuel and full engine oil", "The pilot and unusable fuel only"],
      "Basic empty weight is the standard empty weight plus optional equipment, including unusable fuel, full operating fluids and full engine oil (FAA-H-8083-1B)."),
    S(0, 2, "Overweight", "What happens if you take off above maximum weight?",
      ["Higher stall speed, longer takeoff run and lower climb rate", "Lower stall speed but a longer landing", "Only a higher fuel burn, with no other change"],
      "Extra weight needs more lift: higher stall and takeoff speeds, a longer run, a lower climb rate and ceiling, and more structural load (PHAK chapter 10)."),
]
